package net.officefloor.hq.app.sheet;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * Applies the preview date a screen sends with each read ({@value #HEADER}, yyyy-MM-dd): while the read is
 * answered, {@link SheetStore#today(String)} gives that date in place of the sheet's today, so every figure is
 * worked out as if the sheet's today were that date, over the sheet's current records. The preview belongs to
 * the screen; only a read takes it, so every change still uses the sheet's real today.
 */
@Component
public class PreviewFilter extends OncePerRequestFilter {

    /** The header a screen with a preview date set sends with each read. */
    public static final String HEADER = "X-Preview";

    private static final ThreadLocal<LocalDate> PREVIEW = new ThreadLocal<>();

    /** The preview date of the read being answered, null when none. */
    static LocalDate current() {
        return PREVIEW.get();
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().startsWith("/api/") || !"GET".equals(request.getMethod());
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        LocalDate date = parse(request.getHeader(HEADER));
        if (date == null) {
            chain.doFilter(request, response);
            return;
        }
        PREVIEW.set(date);
        try {
            chain.doFilter(request, response);
        } finally {
            PREVIEW.remove();
        }
    }

    private static LocalDate parse(String text) {
        if (text == null || text.isBlank()) {
            return null;
        }
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            return null;
        }
    }
}
import { useEffect, useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser, usePreview } from '../../session/session';
import { useSheet } from './sheet';

// The screen's preview date: while one is set, every figure shows the sheet's current records as if its today
// were that date. Changes still go through, on the sheet's real today. Only this screen's.
function SheetPreview() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [preview, setPreview] = usePreview();
  const loaded = useSheet(sheet);
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  // A read not keyed by the preview date (plans, openings) is re-read when it is set or cleared.
  const was = useRef(preview);
  useEffect(() => {
    if (was.current === preview) return;
    was.current = preview;
    void queryClient.invalidateQueries({ queryKey: ['sheet'] });
  }, [preview, queryClient]);

  if (!user || sheet === '') return null;
  return (
    <form
      data-testid="preview-form"
      onSubmit={(e) => {
        e.preventDefault();
        const date = input.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(date)) setPreview(date);
      }}
    >
      Preview <strong data-testid="sheet-preview">{loaded.data?.preview ?? ''}</strong>{' '}
      <input data-testid="preview-date" type="date" value={input} onChange={(e) => setInput(e.target.value)} />
      <button type="submit" data-testid="preview-set">
        Preview date
      </button>
      <button type="button" data-testid="preview-clear" onClick={() => setPreview(undefined)}>
        Clear preview
      </button>
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 26, Component: SheetPreview });
import { currentAsOf, currentPreview } from '../session/session';

// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request; `reason` is the text the server answered with (empty when none). */
export class HttpError extends Error {
  constructor(message: string, readonly reason: string, readonly status: number) {
    super(message);
  }
}

/** A change sent from a screen showing the sheet as of a date carries it, so the server refuses it. */
function withAsOf(init?: RequestInit): RequestInit | undefined {
  const asOf = currentAsOf();
  if (init?.method === undefined || asOf === '') return init;
  return { ...init, headers: { ...(init.headers as Record<string, string>), 'X-As-Of': asOf } };
}

/** A read sent from a screen with a preview date set carries it, so the server works every figure out as
 *  if the sheet's today were that date. A change never carries it: it uses the sheet's real today. */
function withPreview(init?: RequestInit): RequestInit | undefined {
  const preview = currentPreview();
  if (init?.method !== undefined || preview === '') return init;
  return { ...init, headers: { ...(init?.headers as Record<string, string> | undefined), 'X-Preview': preview } };
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, withPreview(withAsOf(init)));
  if (!res.ok) {
    const reason = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, reason, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
